import json
import sys
from pathlib import Path

case = Path(sys.argv[1]).resolve()
operation = sys.argv[2]
state_path = case / 'service.json'
state = json.loads(state_path.read_text())
before = state['ticket']['state']
entry = {'operation': operation, 'arguments': sys.argv[3:], 'before': before}
status = 0
if operation == 'read':
    result = state
elif operation == 'schema':
    result = {
        'read': 'Read exact ticket, PR, automation settings and actor',
        'transitions': 'List available transition operations',
        'transition': 'transition <operation-id> <expected-state>; compare-state update',
        'actor': 'fixture-agent, authorized for this test scope',
        'all_operations': ['read', 'schema', 'transitions', 'transition'],
    }
elif operation == 'transitions':
    result = [{'id': 'to-' + name, 'destination': name, 'requiredFields': []}
              for name in ['todo', 'active', 'review', 'qa', 'done']]
elif operation == 'transition':
    target = sys.argv[3].removeprefix('to-')
    expected = sys.argv[4] if len(sys.argv) > 4 else None
    if target not in ['todo', 'active', 'review', 'qa', 'done']:
        result, status = {'error': 'unknown transition'}, 1
    elif expected is not None and expected != before:
        result, status = {'error': 'state changed', 'actual': before}, 1
    else:
        state['ticket']['state'] = target
        state['writeCount'] += 1
        if state.get('timeoutAfterApply') and state['writeCount'] == 1:
            result, status = {'error': 'timeout; outcome unknown'}, 75
        else:
            result = {'accepted': True}
        state_path.write_text(json.dumps(state, indent=2) + '\n')
else:
    result, status = {'error': 'unknown operation'}, 1
entry.update({'result': result, 'exit': status, 'after': state['ticket']['state']})
with (case / 'trace.jsonl').open('a') as log:
    log.write(json.dumps(entry) + '\n')
print(json.dumps(result, indent=2))
sys.exit(status)

